//! Generated bytes retain the same fixed-lettering font license as card_pin.
const plan = @import("keypad_plan.zig");
pub fn Store(comptime section: ?[]const u8) type {
    return if (section != null) struct {
        pub const spans: [@embedFile("keypad_atlas_plan.bin").len]u8 align(64) linksection(".flash.keypad.plan") = @embedFile("keypad_atlas_plan.bin")[0..@embedFile("keypad_atlas_plan.bin").len].*;
        pub const pixels: [@embedFile("keypad_atlas.bin").len]u8 align(64) linksection(".flash.keypad.atlas") = @embedFile("keypad_atlas.bin")[0..@embedFile("keypad_atlas.bin").len].*;
    } else struct {
        pub const spans: [@embedFile("keypad_atlas_plan.bin").len]u8 align(64) = @embedFile("keypad_atlas_plan.bin")[0..@embedFile("keypad_atlas_plan.bin").len].*;
        pub const pixels: [@embedFile("keypad_atlas.bin").len]u8 align(64) = @embedFile("keypad_atlas.bin")[0..@embedFile("keypad_atlas.bin").len].*;
    };
}
pub fn segments(comptime section: ?[]const u8) []const plan.Segment {
    const bytes = &Store(section).spans;
    return @as([*]const plan.Segment, @ptrCast(bytes))[0 .. bytes.len / @sizeOf(plan.Segment)];
}
